--
-- Tablo için tablo yapısı `user_subscriptions`
--

CREATE TABLE `user_subscriptions` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `user_id` bigint(20) UNSIGNED NOT NULL,
  `type` enum('package','vehicle') NOT NULL DEFAULT 'package',
  `user_car_id` bigint(20) UNSIGNED DEFAULT NULL,
  `user_order_id` bigint(20) UNSIGNED DEFAULT NULL,
  `source` enum('payment','trial','admin','legacy') NOT NULL DEFAULT 'payment',
  `package_name` varchar(255) DEFAULT NULL,
  `package_tier` varchar(32) DEFAULT NULL,
  `vehicle_limit` smallint(5) UNSIGNED DEFAULT NULL,
  `plan_months` smallint(5) UNSIGNED DEFAULT NULL,
  `price` decimal(10,2) DEFAULT NULL,
  `vat_amount` decimal(10,2) DEFAULT NULL,
  `total_amount` decimal(10,2) DEFAULT NULL,
  `starts_at` datetime NOT NULL,
  `ends_at` datetime NOT NULL,
  `status` enum('active','inactive') NOT NULL DEFAULT 'active',
  `auto_renew` tinyint(1) NOT NULL DEFAULT 1,
  `renew_attempts` tinyint(3) UNSIGNED NOT NULL DEFAULT 0,
  `last_renew_error` varchar(255) DEFAULT NULL,
  `last_renew_attempt_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

